// ============================================================// KRISHNA// PHARMACY & ALTERNATIVES// ============================================================class Pharmacy {public:int id;string name,location;double distance;unorderedmap<string,int> stock; // medicine name -> unexpired units_string address,city,state,pin,phone,email,opening,closing,status;double latitude = 0, longitude = 0; bool hasCoords = false; bool delivery = false;Pharmacy(int i,string n,string l,double d): id(i),name(n),location(l),distance(d) {}void addMedicine(string m,int q) { stock[m]=q;}bool hasMedicine(string m) const{auto it=stock.nd(m);return it!=stock.end() && it->second>0;}int getStock(string m) const{auto it=stock.nd(m);return it!=stock.end()?it->second:0;}void removeMedicine(string m,int q) {if(hasMedicine(m) && stock[m]>=q) stock[m]-=q;}void show() const{cout << id << "| " << name << "| " << location<< "| " << distance << " km" << endl;}void showMedicineStock() const{cout << "\n" << name << " stock:\n";for(const auto& x:stock) cout << x.rst << ": " << x.second << endl;}Json toJson() const{Json j = Json::object();j["pharmacy_id"]=id; j["name"]=name; j["address"]=address; j["city"]=city;j["state"]=state;j["pin_code"]=pin; j["phone"]=phone; j["email"]=email; j["opening_time"]=opening; j["closing_time"]=closing;j["status"]=status; j["delivery_available"]=delivery; j["items_in_stock"]=(long long)stock.size();if(hasCoords) { j["latitude"]=latitude; j["longitude"]=longitude;}return j;}};void ndPharmacy(vector<Pharmacy>& pharmacies,string medicine) {sort(pharmacies.begin(),pharmacies.end(),[](const Pharmacy& a,const Pharmacy& b){ return a.distance<b.distance;});boolfound=false;cout << "\nPharmacies for " << medicine << ":\n";for(const auto& p:pharmacies) {if(p.hasMedicine(medicine)) {cout << p.name << "- " << p.distance << " km - Stock: "<< p.getStock(medicine) << endl;found=true;}}if(!found) cout << "No pharmacy found.\n";}void ndAlternative(unordered_map<string,Medicine>& inventory,string medicine) {if(inventory.nd(medicine)==inventory.end()) {cout << "Medicine not found.\n";return;}cout << "\nAlternatives for " << medicine << ":\n";inventory[medicine].showAlternatives();}// ---------------- Database: pharmacies & alternatives ----------------void Database::loadAlternatives(unordered_map<string,Medicine>& inventory) {Json rows = query("SELECT m.name med,a.name alt FROM medicine_alternatives x ""JOIN medicines m ON m.medicineid=x.medicineid JOIN medicines__a ON a.medicineid=x.alternativeid "__"ORDER BY x.matchtype='Same composition' DESC, a.name");_for(const auto& r :rows.items()) {auto it=inventory.nd(r.at("med").str());if(it!=inventory.end()) it->second.addAlternative(r.at("alt").str());}}void Database::loadPharmacies(vector<Pharmacy>& pharmacies) {Json rows = query("SELECT pharmacy_id,name,address,city,state,pin_code,latitude,longitude,phone,email,opening_time,""closing_time,status,delivery_available FROM pharmacies ORDER BY pharmacy_id");unorderedmap<int,size_t> index;_for(const auto& r :rows.items()) {Pharmacy p((int)r.at("pharmacy_id").integer(),r.at("name").str(),r.at("address").str()+", "+r.at("city").str(),0.0);p.address=r.at("address").str(); p.city=r.at("city").str(); p.state=r.at("state").str();p.pin=r.at("pin_code").str(); p.phone=r.at("phone").str(); p.email=r.at("email").str();p.opening=r.at("opening_time").str(); p.closing=r.at("closing_time").str();p.status=r.at("status").str();p.delivery=r.at("delivery_available").integer()==1;if(r.at("latitude").isNumber() && r.at("longitude").isNumber()) {p.hasCoords=true; p.latitude=r.at("latitude").num(); p.longitude=r.at("longitude").num();}index[p.id]=pharmacies.size(); pharmacies.push_back(p);}Json st = query("SELECT b.pharmacy_id pid,m.name med,SUM(b.quantity)q FROM medicine_batches b ""JOIN medicines m ON m.medicineid=b.medicineid WHERE b.expiry__date>=date('now') AND b.quantity>0 "_"GROUP BY b.pharmacy_id,b.medicine_id");for(const auto& r : st.items()) {auto it=index.nd((int)r.at("pid").integer());if(it!=index.end()) pharmacies[it->second].addMedicine(r.at("med").str(),(int)r.at("q").integer());}}
